// Page helpers for the report HTML (generated by our templates, so a balanced-tag scan is enough):
// split a report into its `.page` blocks and read plain text. Shared by extract-insight-pages.mjs and make-insight.mjs.
export function elementEnd(html, start, tag) {
  const re = new RegExp(`<${tag}\\b|</${tag}>`, 'g');
  re.lastIndex = start;
  let depth = 0, m;
  while ((m = re.exec(html))) {
    depth += m[0][1] === '/' ? -1 : 1;
    if (depth === 0) return m.index + m[0].length;
  }
  return -1;
}

export function splitPages(html) {
  const re = /<(div|section)\s+class="page(?:\s[^"]*)?"[^>]*>/g;
  re.lastIndex = Math.max(html.search(/<body\b/i), 0);
  const pages = [];
  let m;
  while ((m = re.exec(html))) {
    const end = elementEnd(html, m.index, m[1]);
    if (end < 0) break;
    pages.push(html.slice(m.index, end));
    re.lastIndex = end;
  }
  return pages;
}

const ENT = { nbsp: ' ', amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", mdash: '—', ndash: '–', hellip: '…' };
export const text = h => h
  .replace(/<[^>]+>/g, ' ')
  .replace(/&(#x?[0-9a-f]+|[a-z]+);/gi, (m, e) => {
    if (e[0] === '#') return String.fromCodePoint(e[1] === 'x' || e[1] === 'X' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10));
    return ENT[e.toLowerCase()] ?? m;
  })
  .replace(/\s+/g, ' ').trim();
